using System;
using System.IO;
using System.Net;
using System.Text;
using System.Security.Cryptography;
using System.Collections.Generic;
using System.Threading.Tasks;

partial class Desktop {
 bool assistantWorking;
 string AssistantFile{get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"LibroStudio",args.Length>0&&Array.IndexOf(args,"--self-test")>=0?"aula-selftest.dat":"aula.dat");}}
 Dictionary<string,string> ReadAssistant(){try{if(File.Exists(AssistantFile))return json.Deserialize<Dictionary<string,string>>(Encoding.UTF8.GetString(ProtectedData.Unprotect(File.ReadAllBytes(AssistantFile),Encoding.UTF8.GetBytes("Maquetario aula v1"),DataProtectionScope.CurrentUser)));}catch{}return new Dictionary<string,string>();}
 string ClassProfileUrl(){try{string path=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"maquetario-aula.json");if(File.Exists(path)){var profile=json.Deserialize<Dictionary<string,string>>(File.ReadAllText(path));return profile.ContainsKey("serviceUrl")?profile["serviceUrl"]:"";}}catch{}return "";}
 static Uri AssistantUri(string url){Uri uri;if(!Uri.TryCreate(url,UriKind.Absolute,out uri)||uri.UserInfo.Length>0||uri.Query.Length>0||uri.Fragment.Length>0||uri.Scheme!="https"&&!(uri.Scheme=="http"&&uri.IsLoopback))throw new Exception("Usá una dirección HTTPS del servicio del aula.");return uri;}
 object AssistantStatus(){var cfg=ReadAssistant();string endpoint=cfg.ContainsKey("url")?cfg["url"]:ClassProfileUrl();return new{configured=endpoint.Length>0&&cfg.ContainsKey("code")&&cfg["code"].Length>0,serviceUrl=endpoint,hasProfile=ClassProfileUrl().Length>0};}
 void SaveAssistant(Dictionary<string,object> p){string url=Convert.ToString(p["url"]).Trim(),code=Convert.ToString(p["code"]).Trim();AssistantUri(url);var old=ReadAssistant();if(code.Length==0&&old.ContainsKey("url")&&old["url"]==url&&old.ContainsKey("code"))code=old["code"];if(code.Length<8||code.Length>200)throw new Exception("Ingresá el código de aula provisto por tu docente.");var cfg=new Dictionary<string,string>{{"url",url.TrimEnd('/')},{"code",code},{"device",old.ContainsKey("device")?old["device"]:Guid.NewGuid().ToString("N")}};Directory.CreateDirectory(Path.GetDirectoryName(AssistantFile));File.WriteAllBytes(AssistantFile,ProtectedData.Protect(Encoding.UTF8.GetBytes(json.Serialize(cfg)),Encoding.UTF8.GetBytes("Maquetario aula v1"),DataProtectionScope.CurrentUser));}
 async Task AssistantReview(string id,Dictionary<string,object> p){if(assistantWorking)throw new Exception("Hay una consulta en curso.");if(!p.ContainsKey("consent")||!Convert.ToBoolean(p["consent"]))throw new Exception("Confirmá el envío de esta consulta.");var cfg=ReadAssistant();if(!cfg.ContainsKey("url")||!cfg.ContainsKey("code"))throw new Exception("Primero conectá el aula.");string body=json.Serialize(p["document"]);if(body.Length>60000)throw new Exception("La consulta supera el límite de texto.");assistantWorking=true;try{var url=new Uri(AssistantUri(cfg["url"]).AbsoluteUri.TrimEnd('/')+"/review");var req=(HttpWebRequest)WebRequest.Create(url);req.Method="POST";req.ContentType="application/json";req.AllowAutoRedirect=false;req.Timeout=120000;req.ReadWriteTimeout=120000;req.Headers["Authorization"]="Bearer "+cfg["code"];req.Headers["X-Maquetario-Device"]=cfg["device"];ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;byte[] bytes=Encoding.UTF8.GetBytes(body);req.ContentLength=bytes.Length;using(var stream=await req.GetRequestStreamAsync())await stream.WriteAsync(bytes,0,bytes.Length);using(var response=(HttpWebResponse)await req.GetResponseAsync())using(var reader=new StreamReader(response.GetResponseStream())){string result=await reader.ReadToEndAsync();if(result.Length>200000)throw new Exception("Respuesta del aula demasiado grande.");Reply(id,json.DeserializeObject(result));}}catch(WebException e){var response=e.Response as HttpWebResponse;string message=response!=null&&response.StatusCode==HttpStatusCode.Unauthorized?"Código de aula incorrecto o vencido.":response!=null&&(int)response.StatusCode==429?"El aula alcanzó su límite de consultas. Intentá más tarde.":"No se pudo consultar al aula. Revisá la conexión o avisá a tu docente.";throw new Exception(message);}finally{assistantWorking=false;}}
}
